class Robot {
  constructor(name) {
    this.name = name;
  }

  report() {
    console.log(`${this.name} reporting for duty.`);
  }
}

class ScoutRobot extends Robot {
  constructor(name, range) {
    super(name);
    this.range = range;
  }

  scan() {
    console.log(`${this.name} scans ${this.range} meters ahead.`);
  }

  report() {
    console.log(`${this.name} (scout) reporting — range ${this.range}m.`);
  }
}

const scout = new ScoutRobot("Pathfinder", 40);
scout.report();
scout.scan();

